@Override
    public Result call(Context ctx) throws Throwable {
        pretreatment(ctx);

        //0.检测method
        boolean is_get = ContentTypes.METHOD_GET.equals(ctx.action);
        String url = ctx.url;

        //0.尝试重构url
        // a. GET 方法，统一用 query 参数
        // b. body 提交时，参数转到 query 上（有 NamiBody 的参数 已经从 args 移除了）
        if ((is_get && ctx.args.size() > 0) || (ctx.body != null && ctx.args.size() > 0)) {
            StringBuilder sb = new StringBuilder(ctx.url);
            //如果URL中含有固定参数,应该用'&'添加参数
            sb.append(ctx.url.contains("?") ? "&" : "?");

            for (Map.Entry<String, Object> kv : ctx.args.entrySet()) {
                if (kv.getValue() != null) {
                    sb.append(kv.getKey()).append('=')
                            .append(HttpUtils.urlEncode(kv.getValue().toString()))
                            .append('&');
                }
            }

            url = sb.substring(0, sb.length() - 1);
        }

        if (ctx.config.getDecoder() == null) {
            throw new IllegalArgumentException("There is no matching decoder");
        }

        //0.尝试解码器的过滤
        ctx.config.getDecoder().pretreatment(ctx);

        //0.开始构建http
        HttpUtils http = HttpUtils.http(url).headers(ctx.headers).timeout(ctx.config.getTimeout());
        HttpResponse response = null;


        //1.执行并返回
        if (is_get) {
            response = http.exec(ContentTypes.METHOD_GET);
        } else {
            String contentType = ctx.headers.getOrDefault(ContentTypes.HEADER_CONTENT_TYPE, "");

            if (contentType.length() > 0 &&
                    (contentType.startsWith(ContentTypes.FORM_DATA_VALUE) ||
                            contentType.startsWith(ContentTypes.FORM_URLENCODED_VALUE))) {
                //明确申明用表单模式
                response = formRequest(ctx, http);
            } else {
                //尝试编码模式
                Encoder encoder = null;
                if (contentType.length() > 0) {
                    //动态的最优先
                    encoder = NamiManager.getEncoder(contentType);
                }

                if (encoder == null) {
                    //配置的初始化的第二优先
                    encoder = ctx.config.getEncoder();
                }

                if (encoder != null) {
                    if (encoder.bodyRequired() && ctx.body == null) {
                        throw new NamiException("The encoder requires parameters with '@NamiBody'");
                    }
                }

                //有 body 或者 encoder；则用编码方式
                if (ctx.body != null || encoder != null) {
                    response = bodyRequest(ctx, http, encoder);
                } else {
                    response = formRequest(ctx, http);
                }
            }
        }

        if (response == null) {
            return null;
        }

        //2.构建结果（try-with-resources 确保响应连接归还/关闭）
        try (HttpResponse resp = response) {
            Result result = new Result(resp.code(), resp.bodyAsBytes());

            //2.1.设置头
            for (String name : resp.headerNames()) {
                for (String v : resp.headers(name)) {
                    result.headerAdd(name, v);
                }
            }

            //2.2.设置字符码
            Charset contentEncoding = resp.contentCharset();
            if (contentEncoding != null) {
                result.charsetSet(contentEncoding);
            }

            //3.返回结果
            return result;
        }
    }

public void beanDeliver(BeanWrap bw) {
        if (bw.raw() == null) {
            return;
        }

        //Plugin
        if (bw.raw() instanceof Plugin) {
            //如果是插件，则插入
            throw new IllegalStateException("'Plugin' cannot be component, please use 'LifecycleBean': " + bw.clz().getName());
        }

        String singletonHint = null;

        //LifecycleBean（替代 Plugin，提供组件的生态周期控制）
        if (bw.raw() instanceof LifecycleBean) {
            //让注解产生的生命周期，排序晚1个点
            int index = bw.index();
            if (index == 0) {
                index = org.noear.solon.core.util.IndexUtil.buildLifecycleIndex(bw.rawClz());
            }

            lifecycle(index + 1, bw.raw());
            singletonHint = "LifecycleBean";
        }

        //EventListener
        if (bw.raw() instanceof EventListener) {
            addEventListener(bw.clz(), bw);
            singletonHint = "EventListener";
        }

        ///////////////////////

        if (app() == null) {
            return;
        }

        //LoadBalance.Factory
        if (bw.raw() instanceof LoadBalance.Factory) {
            FactoryManager.getGlobal().loadBalanceFactory(bw.raw());
            singletonHint = "LoadBalance.Factory";
        }

        //Handler
        if (bw.raw() instanceof Handler) {
            //不再支持 @Bean, @Managed @Mapping fun() //v3.0
            Mapping mapping = bw.clz().getAnnotation(Mapping.class);
            if (mapping != null) {
                app().router().add(bw);
                singletonHint = "Handler";
            }
        }

        //Serializer
        if (bw.raw() instanceof Serializer) {
            app().serializers().register(bw.name(), bw.raw());
            singletonHint = "Serializer";
        }

        //Render
        if (bw.raw() instanceof Render) {
            //指定 mapping
            if (Assert.isNotEmpty(bw.name())) {
                app().renders().register(bw.name(), (Render) bw.raw());
            }

            //接口 mapping
            app().renders().register((Render) bw.raw());

            singletonHint = "Render";
        }

        //EntityConverter //v3.6
        if (bw.raw() instanceof EntityConverter) {
            app().chains().addEntityConverter(bw.raw(), bw.index());
            singletonHint = "EntityConverter";
        }

        //Filter
        if (bw.raw() instanceof Filter) {
            app().router().filter(bw.index(), bw.raw());
            singletonHint = "Filter";
        }

        //RouterInterceptor
        if (bw.raw() instanceof RouterInterceptor) {
            app().router().routerInterceptor(bw.index(), bw.raw());
            singletonHint = "RouterInterceptor";
        }

        //ReturnValueHandler
        if (bw.raw() instanceof ReturnValueHandler) {
            app().chains().addReturnHandler(bw.raw(), bw.index());
            singletonHint = "ReturnValueHandler";
        }

        //MethodArgumentResolver
        if (bw.raw() instanceof MethodArgumentResolver) {
            app().chains().addArgumentResolver(bw.raw(), bw.index());
            singletonHint = "MethodArgumentResolver";
        }

        //Converter
        if (bw.raw() instanceof Converter) {
            Converter c = bw.raw();
            app().converters().register(c);
            singletonHint = "Converter";
        }

        //ConverterFactory
        if (bw.raw() instanceof ConverterFactory) {
            ConverterFactory cf = bw.raw();
            app().converters().register(cf);
            singletonHint = "ConverterFactory";
        }


        if (bw.singleton() == false && singletonHint != null) {
            log.warn(singletonHint + " does not support @Singleton(false), class=" + bw.clz().getName());
        }
    }

